ALTER TABLE "tipaje_sanguineo" ADD FOREIGN KEY ("usuario_registrador_id") REFERENCES "usuario" ("usuario_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consulta" ADD FOREIGN KEY ("paciente_id") REFERENCES "paciente" ("paciente_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "consulta" ADD FOREIGN KEY ("usuario_medico_id") REFERENCES "usuario" ("usuario_id") DEFERRABLE INITIALLY IMMEDIATE;

